/// <summary>
/// clean up table for anything older than 14 days
/// </summary>
static void cleanUpPostSalesOrderCreationProcessingQueue()
{
    utcdatetime cutOffDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -14);

    METSalesOrderShipmentConfirmationQueue postSalesORderCreationProcessingQueue;
    METSalesOrderShipmentConfirmationQueue::skip(postSalesORderCreationProcessingQueue);

    ttsbegin;
    delete_from postSalesORderCreationProcessingQueue
    where postSalesORderCreationProcessingQueue.CreatedDateTime <= cutOffDateTime;
    ttscommit;
}

/// <summary>
/// skip method for performance purpose
/// </summary>
/// <param name = "_salesOrderShipmentConfirmationQueue"><c>METPostSalesOrderCreationProcessingQueue</c> record</param>
private static void skip(METSalesOrderShipmentConfirmationQueue _salesOrderShipmentConfirmationQueue)
{
    _salesOrderShipmentConfirmationQueue.skipDatabaseLog(true);
    _salesOrderShipmentConfirmationQueue.skipDataMethods(true);
    _salesOrderShipmentConfirmationQueue.skipDeleteActions(true);
    _salesOrderShipmentConfirmationQueue.skipEvents(true);
    _salesOrderShipmentConfirmationQueue.skipBusinessEvents(true);
}
